sys_script_include.script:
var AI_DeviceUtils = Class.create();
AI_DeviceUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getDescription: function() {
        var sysId = this.getParameter('sys_id');
        if (!sysId) return '';

        var gr = new GlideRecord('x_15581_servicenow_ai_devices');
        if (gr.get(sysId)) {
            return gr.getValue('short_description'); // IMPORTANT: field in your AI Devices table
        }
        return '';
    }

});
